mapper.select:
select
    *
from b_xiecheng_colliding_data_rob
where is_delete = 1
     and update_time < #{startTime}
order by update_time asc limit #{size};

mapper.delete:
delete from b_xiecheng_colliding_data_rob
where id in

    #{id}

limit #{size};

mapper.select:
select a.id  from b_xiecheng_colliding_data_rob a left join b_xiecheng_colliding_data_contrast b
                                                on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_deleted = 0 and b.rule_type_flag =#{ruleTypeFlag}
             where   b.id is null   limit #{xieChengCleanLimitCount}

select a.id  from b_xiecheng_colliding_data_rob a  join b_xiecheng_colliding_data_contrast b
                                                            on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_deleted = 0 and b.rule_type_flag =#{ruleTypeFlag}
where   limit #{xieChengCleanLimitCount}
